import{decodeSimulator078}from'../simulator-codec-078.js';
import{fetchCohortJSON}from'../current-cohort-loader.js';
const d=decodeSimulator078(await fetchCohortJSON('./evidence-090.json.gz')),$=id=>document.getElementById(id),h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=x=>'$'+Math.round(x).toLocaleString();let page=0;
function render(){const c=$('cohort').value,q=$('search').value.toLowerCase(),s=d.summary.find(r=>r.cohort===c),rs=d.rows.filter(r=>(c==='all'?r.cohort!=='grok075':r.cohort===c)&&($('outcome').value==='all'||$('outcome').value==='noTop'&&!r.afterTop.length||$('outcome').value==='noDegree'&&!r.afterTop.some(o=>o.routes.some(z=>['college','graduate'].includes(z.key)))||$('outcome').value==='changed'&&r.afterTop.some(o=>!r.beforeTop.some(z=>z.id===o.id)))&&(!q||(r.name+' '+r.id+' '+r.extra.map(o=>o.title).join(' ')).toLowerCase().includes(q)));page=Math.min(page,Math.max(0,Math.ceil(rs.length/40)-1));$('totals').innerHTML=[['Supported Top',s.beforeTop,s.afterTop],['Bachelor / graduate Top',s.beforeDegree,s.afterDegree],['No-degree Top',s.beforeNoDegree,s.afterNoDegree],['Any supported bachelor / graduate option',s.beforeAllDegree,s.afterAllDegree]].map(([label,a,b])=>`<div class="metric">${h(label)}<b>${a} → ${b}</b>of ${s.models}</div>`).join('');$('count').textContent=rs.length+' models · '+(rs.length?page*40+1:0)+'–'+Math.min(rs.length,(page+1)*40);$('models').innerHTML=rs.slice(page*40,page*40+40).map(r=>`<tr><td><a href="../results-board.html?model=${encodeURIComponent(r.id)}">${h(r.name)}</a><small>${h(r.id)} · ${h(r.cohort)}</small></td><td>${r.beforeTop.map(o=>h(o.title)).join('<br>')||'No supported Top'}</td><td>${(r.afterTop.map(o=>h(o.title)).join('<br>')||'No supported Top')+'<details><summary>All supported degree options ('+r.supportedDegree.length+')</summary>'+r.supportedDegree.map(o=>h(o.title)).join('<br>')+'</details>'}</td><td>${r.extra.map(o=>`${h(o.title)} · <strong>${o.candidate?'Explore':'Supported'}</strong> · ${money(o.entry)}`).join('<br>')||'No added invitation'}</td><td>${r.answers.length} questions<small>${r.unknown} unknown</small><details><summary>Exact checks</summary>${r.answers.map(a=>{const q={prompt:a.prompt||d.catalog[a.careerId]?.questions.find(q=>q.id===a.questionId)?.prompt};return `<p>${h(q.prompt)}<br><b>${h(a.response)}</b><small>${h(a.stage==='diagnostic-only'?'Diagnostic only; does not establish support':a.evidence||a.reason||'')}</small>${(a.evidenceRefs||[]).map(e=>'<small>'+h(e.feature)+': '+h(e.quote)+'</small>').join('')}</p>`;}).join('')}</details></td></tr>`).join('');$('prev').disabled=page===0;$('next').disabled=(page+1)*40>=rs.length;}
$('outcome').onchange=()=>{page=0;render();};$('cohort').onchange=()=>{page=0;render();};$('search').oninput=()=>{page=0;render();};$('prev').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};const requested087=new URL(location.href).searchParams.get('model');if(requested087){const r=d.rows.find(r=>r.id===requested087);if(r){$('cohort').value=r.cohort==='grok075'?'grok075':'all';$('search').value=r.id;}}$('inventory').innerHTML=Object.values(d.catalog).map(o=>`<details><summary>${h(o.title)} · ${money(o.salary.entry)} proxy / year</summary><p>${h(o.preparation.typicalEducation[0])}</p><p>${h(o.salary.geography)} · ${h(o.salary.period)} · ${h(o.salary.basis)}</p><ol>${o.questions.map(q=>'<li>'+h(q.prompt)+'</li>').join('')}</ol><a href="${h(o.sourceURL)}">Occupation source</a> · <a href="${h(o.salary.sourceURL)}">Wage source</a></details>`).join('');$('limits').innerHTML=d.limits.map(x=>'<li>'+h(x)+'</li>').join('');render();
